import { Check, X } from "lucide-react";

interface Props {
  options: string[];
  correctAnswer: string;
  selectedAnswer: string | null;
  revealed: boolean;
  disabled: boolean;
  onSelect: (answer: string) => void;
}

export function OptionList({
  options,
  correctAnswer,
  selectedAnswer,
  revealed,
  disabled,
  onSelect,
}: Props) {
  return (
    <div className="space-y-3">
      {options.map((opt, i) => {
        const isSelected = selectedAnswer === opt;
        const isCorrect = opt === correctAnswer;

        let bg = "bg-slate-800/40 border-slate-600/50";
        if (revealed) {
          if (isCorrect) bg = "bg-emerald-500/30 border-emerald-400";
          else if (isSelected) bg = "bg-red-500/30 border-red-400";
        } else if (isSelected) {
          bg = "bg-emerald-500/30 border-emerald-400";
        }

        return (
          <button
            key={i}
            onClick={() => onSelect(opt)}
            disabled={disabled}
            className={`w-full p-4 rounded-2xl border-2 text-left transition-all ${bg} ${
              !disabled ? "hover:border-slate-500 active:scale-[0.98]" : ""
            }`}
          >
            <div className="flex items-center gap-3">
              <span
                className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold ${
                  revealed && isCorrect
                    ? "bg-emerald-500 text-white"
                    : revealed && isSelected && !isCorrect
                    ? "bg-red-500 text-white"
                    : isSelected
                    ? "bg-emerald-500 text-white"
                    : "bg-slate-700 text-slate-300"
                }`}
              >
                {revealed && isCorrect ? (
                  <Check size={14} />
                ) : revealed && isSelected && !isCorrect ? (
                  <X size={14} />
                ) : (
                  String.fromCharCode(65 + i)
                )}
              </span>
              <span
                className={`${
                  revealed && isCorrect
                    ? "text-emerald-200"
                    : revealed && isSelected && !isCorrect
                    ? "text-red-200"
                    : "text-slate-200"
                }`}
              >
                {opt}
              </span>
            </div>
          </button>
        );
      })}
    </div>
  );
}
