import { supabase } from "@/utils/supabase";
import { getUserInfo } from "@/utils/userInfo";

export interface RedeemReward {
  targetLevel: number;
  coins: number;
}

export interface RedeemCodeInfo {
  code: string;
  target_level: number;
  coins: number;
  description: string | null;
}

export type RedeemResult =
  | { success: true; reward: RedeemReward; description: string | null }
  | { success: false; message: string };

export async function redeemCode(rawCode: string): Promise<RedeemResult> {
  const code = rawCode.trim().toUpperCase();
  if (!code) {
    return { success: false, message: "请输入口令" };
  }

  const userInfo = getUserInfo();
  if (!userInfo.uuid) {
    return { success: false, message: "用户信息缺失，请刷新后重试" };
  }

  try {
    const { data: codeRows, error: codeError } = await supabase
      .from("redeem_codes")
      .select("code, target_level, coins, description, active")
      .eq("code", code)
      .limit(1);

    if (codeError) {
      console.error("查询口令失败:", codeError.message);
      return { success: false, message: "口令服务暂不可用，请稍后再试" };
    }

    if (!codeRows || codeRows.length === 0) {
      return { success: false, message: "口令不存在" };
    }

    const codeInfo = codeRows[0] as RedeemCodeInfo & { active: boolean };
    if (codeInfo.active === false) {
      return { success: false, message: "该口令已失效" };
    }

    const { error: redeemError } = await supabase
      .from("redeem_records")
      .insert({
        code,
        uuid: userInfo.uuid,
        nickname: userInfo.nickname,
        redeemed_at: Date.now(),
      });

    if (redeemError) {
      const msg = String(redeemError.message || "");
      if (
        /duplicate/i.test(msg) ||
        /unique/i.test(msg) ||
        /23505/.test(msg) ||
        /conflict/i.test(msg)
      ) {
        return { success: false, message: "该口令已使用过" };
      }
      console.error("核销口令失败:", redeemError.message);
      return { success: false, message: "核销失败，请稍后再试" };
    }

    return {
      success: true,
      reward: {
        targetLevel: codeInfo.target_level,
        coins: codeInfo.coins,
      },
      description: codeInfo.description,
    };
  } catch (e) {
    console.error("兑换异常:", e);
    return { success: false, message: "网络异常，请稍后再试" };
  }
}
