import { useState, useEffect } from "react";
import { Frown, Home } from "lucide-react";
import { useGameStore } from "@/store/useGameStore";
import { useWordStore } from "@/store/useWordStore";
import ConfirmModal from "@/components/ConfirmModal";

const END_COUNTDOWN_SECONDS = 10;

interface FailModalProps {
  open: boolean;
  onUseItem?: () => void;
  onGoHome?: () => void;
}

export default function FailModal({ open, onUseItem, onGoHome }: FailModalProps) {
  const level = useGameStore((s) => s.level);
  const remainingBricks = useGameStore((s) => s.remainingBricks);
  const inventory = useGameStore((s) => s.inventory);
  const initGame = useGameStore((s) => s.initGame) as (resetLevel?: boolean, resetProgress?: boolean) => void;
  const resetProgressOnFail = useGameStore((s) => s.resetProgressOnFail);
  const resetLevelSessions = useWordStore((s) => s.resetLevelSessions);
  const quizSessionsLeft = useWordStore((s) => s.quizSessionsLeft);

  const [showEndConfirm, setShowEndConfirm] = useState(false);
  const [endCountdown, setEndCountdown] = useState(END_COUNTDOWN_SECONDS);

  useEffect(() => {
    if (!open || quizSessionsLeft <= 0) {
      setEndCountdown(0);
      return;
    }
    setEndCountdown(END_COUNTDOWN_SECONDS);
    const timer = setInterval(() => {
      setEndCountdown((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [open, quizSessionsLeft]);

  useEffect(() => {
    if (open && quizSessionsLeft <= 0) {
      resetProgressOnFail();
    }
  }, [open, quizSessionsLeft, resetProgressOnFail]);

  if (!open) return null;

  const availableItems = Object.entries(inventory)
    .filter(([_, count]) => count > 0 && _ !== "hint")
    .map(([type, count]) => ({ type, count }));

  const totalItems = availableItems.reduce((sum, item) => sum + item.count, 0);

  const hasReviveChance = quizSessionsLeft > 0;

  const endGame = () => {
    resetLevelSessions(1);
    if (hasReviveChance) {
      initGame(true, true);
    } else {
      resetProgressOnFail();
      initGame(true, false);
    }
    setShowEndConfirm(false);
  };

  const handleEndClick = () => {
    if (endCountdown > 0) return;
    if (hasReviveChance) {
      setShowEndConfirm(true);
    } else {
      endGame();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-md" />
      <div className="relative bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border border-red-500/30 rounded-3xl p-8 sm:p-12 max-w-md w-full shadow-2xl text-center">
        <div className="absolute -top-6 left-1/2 -translate-x-1/2">
          <div className="w-12 h-12 rounded-full bg-gradient-to-br from-red-400 to-rose-500 flex items-center justify-center shadow-lg shadow-red-500/50">
            <Frown className="text-white" size={24} />
          </div>
        </div>

        <h2 className="text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-red-400 via-rose-400 to-pink-500 mb-3 mt-4">
          第 {level} 关失败
        </h2>

        <p className="text-slate-400 mb-6">
          场上还剩 {remainingBricks} 个砖块，但已经无法消除了
        </p>

        {hasReviveChance && totalItems > 0 && (
          <>
            <div className="mb-4 p-4 bg-slate-800/50 rounded-xl border border-slate-700">
              <p className="text-slate-300 mb-2">你有 <span className="text-amber-400 font-bold">{totalItems}</span> 个道具可以使用</p>
              <p className="text-slate-500 text-sm">点击下方按钮后，在游戏界面使用道具</p>
            </div>
            <button
              onClick={() => onUseItem?.()}
              className="w-full py-4 mb-3 bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 text-white font-bold text-lg rounded-xl transition-all shadow-lg shadow-amber-500/30 hover:shadow-amber-500/50 flex items-center justify-center gap-2"
            >
              使用道具
            </button>
          </>
        )}

        {hasReviveChance && (
          <div className="mb-4 p-4 bg-violet-500/10 rounded-xl border border-violet-500/30">
            <p className="text-violet-200 text-sm">
              你还有 <span className="text-violet-300 font-bold">{quizSessionsLeft}</span> 次答题复活机会
            </p>
            <p className="text-slate-500 text-xs mt-1">可通过答题继续本关挑战</p>
          </div>
        )}

        <button
          onClick={handleEndClick}
          disabled={endCountdown > 0}
          className={`w-full py-4 mb-3 font-bold text-lg rounded-xl transition-all shadow-lg flex items-center justify-center gap-2 ${
            endCountdown > 0
              ? "bg-slate-600/50 text-slate-400 cursor-not-allowed shadow-rose-500/10"
              : "bg-gradient-to-r from-red-500 via-rose-500 to-pink-500 hover:from-red-400 hover:via-rose-400 hover:to-pink-400 text-white shadow-rose-500/30 hover:shadow-rose-500/50"
          }`}
        >
          游戏结束{endCountdown > 0 ? ` (${endCountdown}s)` : ""}
        </button>

        <button
          onClick={() => onGoHome?.()}
          className="w-full py-3 bg-slate-700/50 hover:bg-slate-600/50 text-slate-300 rounded-xl transition-all border border-slate-600/50 flex items-center justify-center gap-2"
        >
          <Home size={16} />
          返回首页
        </button>
      </div>

      <ConfirmModal
        open={showEndConfirm}
        title="确认结束游戏？"
        message={`你还有 ${quizSessionsLeft} 次答题复活机会，结束游戏将失去本次挑战进度。确定要结束吗？`}
        confirmText="确认结束"
        cancelText="继续挑战"
        onConfirm={endGame}
        onCancel={() => setShowEndConfirm(false)}
      />
    </div>
  );
}
