import { useEffect, useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { ArrowLeft, Sun, Truck, Package, CheckCircle2, X, Weight, Zap, Brain, Loader2 } from "lucide-react";
import { useGameStore } from "@/store/useGameStore";
import { useDeliveryStore, isOrderFullyLoaded } from "@/store/useDeliveryStore";
import { generateOrders } from "@/utils/orderGenerator";
import { DeliveryOrder } from "@/types/delivery";
import { SEED_CONFIGS } from "@/types/game";
import QuizModal from "@/components/QuizModal";
import { useWordStore } from "@/store/useWordStore";

const DAILY_ORDERS_KEY = "block_game_daily_orders_date";

function getTodayStr(): string {
  const d = new Date();
  return `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}`;
}

export default function DeliveryHub() {
  const navigate = useNavigate();
  const sunlight = useGameStore((s) => s.sunlight);
  const { availableOrders, setAvailableOrders, acceptOrder, currentOrder, lastCompletedReward, clearLastReward, startTestRun, phase } =
    useDeliveryStore();
  const quizSession = useWordStore((s) => s.quizSession);

  const [showQuiz, setShowQuiz] = useState(false);
  const [loading, setLoading] = useState(false);
  const loadingRef = useRef(false);

  const doRefreshOrdersAsync = (append: boolean = false) => {
    if (loadingRef.current) return;
    loadingRef.current = true;
    setLoading(true);
    // 先让浏览器渲染出 loading 状态，再开始生成订单
    setTimeout(() => {
      const orders = generateOrders(1);
      if (append) {
        // 追加模式：把新订单加到现有列表后面
        const current = useDeliveryStore.getState().availableOrders;
        setAvailableOrders([...current, ...orders]);
      } else {
        // 覆盖模式：用于每天首次访问
        setAvailableOrders(orders);
      }
      loadingRef.current = false;
      setLoading(false);
    }, 30);
  };

  // 进入页面时，只有当天首次访问才自动生成1个免费订单
  // （第二天访问直接清空之前堆积的订单，重新生成1条）
  useEffect(() => {
    const savedDate = localStorage.getItem(DAILY_ORDERS_KEY);
    const today = getTodayStr();
    if (savedDate !== today) {
      localStorage.setItem(DAILY_ORDERS_KEY, today);
      doRefreshOrdersAsync(false); // 覆盖模式：清空旧订单，生成1条新的
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleRefreshClick = () => {
    setShowQuiz(true);
  };

  // 如果有进行中的订单，根据阶段跳转到对应页面
  useEffect(() => {
    if (currentOrder) {
      if (phase === "delivering" || isOrderFullyLoaded(currentOrder)) {
        navigate("/delivery/map");
      } else {
        navigate("/delivery/loading");
      }
    }
  }, [currentOrder, phase, navigate]);

  return (
    <div className="h-screen bg-gradient-to-br from-slate-900 via-amber-950 to-slate-900 flex flex-col">
      <div className="max-w-md mx-auto w-full flex-1 flex flex-col min-h-0">
        <div className="px-4 py-6 shrink-0">
        {/* 顶部栏 */}
        <div className="flex items-center justify-between mb-6">
          <button
            onClick={() => navigate("/farm")}
            className="p-2 rounded-full hover:bg-slate-700/50 text-slate-400 hover:text-slate-200 transition-all"
          >
            <ArrowLeft size={22} />
          </button>
          <h1 className="text-xl font-bold text-amber-300 flex items-center gap-2">
            <Truck size={22} />
            鲜果速递
          </h1>
          <div className="flex items-center gap-1">
            <Sun size={18} className="text-yellow-400" />
            <span className="text-yellow-300 font-bold">{sunlight}</span>
          </div>
        </div>

        {/* 说明 */}
        <div className="bg-slate-800/40 rounded-xl p-3 mb-4 border border-slate-700/40">
          <p className="text-slate-300 text-xs">
            📦 接下订单后，把仓库里的水果装车，开货车送到收货点，完成后获得阳光☀️奖励！
          </p>
        </div>

        {/* 测试入口 - 直接进入驾驶游戏（仅开发环境） */}
        {import.meta.env.DEV && (
        <div className="bg-gradient-to-br from-purple-900/30 to-slate-800/40 rounded-xl p-3 mb-4 border border-purple-500/30">
          <button
            onClick={() => {
              startTestRun();
              navigate("/delivery/map");
            }}
            className="w-full py-2.5 bg-purple-600/50 hover:bg-purple-500/60 text-purple-200 text-xs font-bold rounded-lg transition-all active:scale-95 border border-purple-500/30 flex items-center justify-center gap-2"
          >
            <Zap size={14} />
            测试模式 - 直接进入驾驶
          </button>
        </div>
        )}

        {/* 刷新按钮 */}
        <div className="flex justify-between items-center mb-3">
          <p className="text-slate-400 text-sm font-medium">可接订单</p>
          <button
            onClick={handleRefreshClick}
            disabled={loading}
            className="flex items-center gap-1 px-3 py-1.5 text-xs rounded-lg transition-all bg-violet-600/50 hover:bg-violet-500/60 text-violet-200 border border-violet-500/30 disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {loading ? <Loader2 size={14} className="animate-spin" /> : <Brain size={14} />}
            答题刷新
          </button>
        </div>
        </div>

        {/* 订单列表 - 滚动区域 */}
        <div className="flex-1 overflow-y-auto px-4 min-h-0">
        <div className="space-y-3 pb-4">
          {loading && (
            <div className="text-center py-12 text-slate-500">
              <Loader2 size={32} className="mx-auto mb-3 text-violet-400 animate-spin" />
              <p className="text-sm text-slate-400">正在生成订单…</p>
            </div>
          )}

          {!loading && availableOrders.length === 0 && (
            <div className="text-center py-8 text-slate-500">
              <Package size={32} className="mx-auto mb-2 opacity-40" />
              <p className="text-sm">暂时没有可接订单</p>
              <p className="text-xs text-slate-600 mt-1">点击右上角「答题刷新」获取新订单</p>
            </div>
          )}

          {!loading && availableOrders.map((order) => (
            <OrderCard
              key={order.id}
              order={order}
              onAccept={() => acceptOrder(order.id)}
            />
          ))}
        </div>
        </div>
      </div>

      {/* 配送完成奖励弹窗 */}
      {lastCompletedReward && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm">
          <div className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-2xl p-6 border border-emerald-500/30 text-center max-w-xs mx-4 relative">
            <button
              onClick={clearLastReward}
              className="absolute top-3 right-3 p-1 text-slate-400 hover:text-slate-200"
            >
              <X size={18} />
            </button>
            <CheckCircle2 size={48} className="mx-auto mb-3 text-emerald-400" />
            <h2 className="text-xl font-bold text-emerald-300 mb-2">配送成功！</h2>
            <p className="text-slate-400 text-sm mb-3">
              获得 <span className="text-yellow-300 font-bold text-lg">{lastCompletedReward.reward}</span> 阳光 ☀️
            </p>
            <button
              onClick={clearLastReward}
              className="mt-2 w-full py-2 bg-gradient-to-r from-emerald-500 to-teal-500 text-white font-bold rounded-lg hover:opacity-90"
            >
              继续接单
            </button>
          </div>
        </div>
      )}

      <QuizModal
        open={showQuiz}
        onClose={() => {
          const won = quizSession?.isFinished && quizSession?.isWon;
          setShowQuiz(false);
          if (won) {
            doRefreshOrdersAsync(true); // 答题通过：追加1条新订单
          }
        }}
        mode="refresh"
      />
    </div>
  );
}

function OrderCard({
  order,
  onAccept,
}: {
  order: DeliveryOrder;
  onAccept: () => void;
}) {
  return (
    <div className="bg-slate-800/60 rounded-xl p-4 border border-slate-700/40 backdrop-blur-sm">
      {/* 任务要求 */}
      <div className="space-y-1.5 mb-3">
        {order.conditions.map((cond, idx) => {
          if (cond.type === "exact") {
            const cfg = SEED_CONFIGS[cond.seedType];
            return (
              <div key={idx} className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <span className="text-lg w-6 text-center">{cfg.fruitEmoji}</span>
                  <span className="text-slate-300">{cfg.name}</span>
                </div>
                <span className="text-sky-300">必须正好 × {cond.count}</span>
              </div>
            );
          }
          if (cond.type === "min") {
            const cfg = SEED_CONFIGS[cond.seedType];
            return (
              <div key={idx} className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <span className="text-lg w-6 text-center">{cfg.fruitEmoji}</span>
                  <span className="text-slate-300">{cfg.name}</span>
                </div>
                <span className="text-emerald-300">至少 × {cond.count}</span>
              </div>
            );
          }
          if (cond.type === "max") {
            const cfg = SEED_CONFIGS[cond.seedType];
            return (
              <div key={idx} className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <span className="text-lg w-6 text-center">{cfg.fruitEmoji}</span>
                  <span className="text-slate-300">{cfg.name}</span>
                </div>
                <span className="text-amber-300">不超过 × {cond.count}</span>
              </div>
            );
          }
          if (cond.type === "forbidden") {
            return (
              <div key={idx} className="flex items-center justify-between text-sm">
                <span>
                  {cond.seedTypes.map((s, i) => (
                    <span key={i} className="text-lg w-6 text-center inline-block">
                      {SEED_CONFIGS[s].fruitEmoji}
                    </span>
                  ))}
                </span>
                <span className="text-rose-300">禁止使用</span>
              </div>
            );
          }
          return null;
        })}
      </div>

      {/* 任务信息 */}
      <div className="mb-3 px-3 py-2 bg-slate-700/30 border border-slate-600/30 rounded-lg">
        <p className="text-slate-300 text-xs flex items-center gap-1.5">
          <Weight size={12} className="text-amber-400" />
          目标重量：<span className="font-bold text-amber-300">≥ {order.targetWeight}</span>
          <span className="text-slate-500">（限重 {order.maxWeight}）</span>
        </p>
      </div>

      {/* 底部：奖励 + 接单 */}
      <div className="flex items-center justify-between pt-3 border-t border-slate-700/40">
        <div className="flex items-center gap-1">
          <Sun size={16} className="text-yellow-400" />
          <span className="font-bold text-yellow-300">
            {order.baseReward}
          </span>
        </div>
        <button
          onClick={onAccept}
          className="px-4 py-2 text-sm font-bold rounded-lg transition-all bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-white active:scale-95 shadow-lg shadow-emerald-500/20"
        >
          接单
        </button>
      </div>
    </div>
  );
}
