import { useState, useRef, useEffect, useCallback } from "react";
import { Sparkles, Sun } from "lucide-react";
import { SeedType, SEED_CONFIGS } from "@/types/game";
import { audioManager } from "@/utils/audioManager";
import { useFarmStore } from "@/store/useFarmStore";
import { useGameStore } from "@/store/useGameStore";

const REEL_SYMBOLS: SeedType[] = [
  "carrot", "cucumber", "cabbage", "strawberry",
  "tomato", "corn", "sunflower", "watermelon", "kiwi",
];

// 每种水果对应种子奖励数量
const REWARD_SEED_AMOUNT: Record<SeedType, number> = {
  carrot: 2, cucumber: 2, cabbage: 2, strawberry: 2,
  tomato: 2, corn: 2, sunflower: 1, watermelon: 1, kiwi: 2,
  grapes: 1, eggplant: 2,
};

const REEL_HEIGHT = 56;
const SPIN_DURATION_BASE = 1400;
const SPIN_DURATION_STEP = 400;
// 中奖概率：预先决定本次是否中奖，中奖则三盘同 fruit，不中则强制不全同
const WIN_RATE = 0.3;

interface ReelState {
  spinning: boolean;
  finalType: SeedType | null;
  offset: number;
}

export default function SlotMachineReward({ onClose }: { onClose: () => void }) {
  const [reels, setReels] = useState<ReelState[]>([
    { spinning: false, finalType: null, offset: 0 },
    { spinning: false, finalType: null, offset: 0 },
    { spinning: false, finalType: null, offset: 0 },
  ]);
  const [spinning, setSpinning] = useState(false);
  const [result, setResult] = useState<SeedType | null>(null);
  // 奖励：已解锁发种子；未解锁折算成阳光
  const [rewardSeed, setRewardSeed] = useState<{ type: SeedType; amount: number } | null>(null);
  const [rewardSunlight, setRewardSunlight] = useState(0);
  const [showReward, setShowReward] = useState(false);
  const spinTimers = useRef<number[]>([]);

  const grantSeed = useFarmStore((s) => s.grantSeed);
  const unlockedSeeds = useFarmStore((s) => s.unlockedSeeds);
  const addSunlight = useGameStore((s) => s.addSunlight);

  useEffect(() => {
    return () => { spinTimers.current.forEach((t) => clearTimeout(t)); };
  }, []);

  const spin = useCallback(() => {
    if (spinning) return;
    setSpinning(true);
    setResult(null);
    setShowReward(false);
    setRewardSeed(null);
    setRewardSunlight(0);
    audioManager.playMoveSfx();

    // 预先决定本次是否中奖，再据此生成转盘结果
    const isWin = Math.random() < WIN_RATE;
    let finalTypes: SeedType[];
    if (isWin) {
      const s = REEL_SYMBOLS[Math.floor(Math.random() * REEL_SYMBOLS.length)];
      finalTypes = [s, s, s];
    } else {
      // 不中奖：保证三盘不全相同
      const s1 = REEL_SYMBOLS[Math.floor(Math.random() * REEL_SYMBOLS.length)];
      const s2 = REEL_SYMBOLS[Math.floor(Math.random() * REEL_SYMBOLS.length)];
      let s3 = REEL_SYMBOLS[Math.floor(Math.random() * REEL_SYMBOLS.length)];
      if (s1 === s2 && s2 === s3) {
        let alt = REEL_SYMBOLS[Math.floor(Math.random() * REEL_SYMBOLS.length)];
        while (alt === s1) alt = REEL_SYMBOLS[Math.floor(Math.random() * REEL_SYMBOLS.length)];
        s3 = alt;
      }
      finalTypes = [s1, s2, s3];
    }

    // 每个转盘依次停止
    const newReels: ReelState[] = finalTypes.map((t) => ({ spinning: true, finalType: t, offset: 0 }));
    setReels(newReels);

    finalTypes.forEach((_, i) => {
      const duration = SPIN_DURATION_BASE + i * SPIN_DURATION_STEP;
      const timer = window.setTimeout(() => {
        setReels((prev) => {
          const next = [...prev];
          next[i] = { spinning: false, finalType: finalTypes[i], offset: 0 };
          return next;
        });
        audioManager.playClearSfx();
        // 全部停止
        if (i === finalTypes.length - 1) {
          window.setTimeout(() => {
            const allSame = finalTypes.every((t) => t === finalTypes[0]);
            if (allSame) {
              const seedType = finalTypes[0];
              const amount = REWARD_SEED_AMOUNT[seedType];
              if (unlockedSeeds.includes(seedType)) {
                // 已解锁：直接发放种子到农场库存
                for (let k = 0; k < amount; k++) grantSeed(seedType);
                setRewardSeed({ type: seedType, amount });
                setRewardSunlight(0);
              } else {
                // 未解锁：折算成该种子的阳光价值发放
                const sunlight = SEED_CONFIGS[seedType].sunlightPrice * amount;
                addSunlight(sunlight);
                setRewardSeed(null);
                setRewardSunlight(sunlight);
              }
              setResult(seedType);
              setShowReward(true);
              audioManager.playWinSfx();
            } else {
              setResult(null);
              setShowReward(true);
            }
            setSpinning(false);
          }, 200);
        }
      }, duration);
      spinTimers.current.push(timer);
    });
  }, [spinning, grantSeed, unlockedSeeds, addSunlight]);

  const allSame = reels.every((r) => r.finalType === reels[0].finalType && !r.spinning && r.finalType !== null);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md px-6" onClick={showReward ? onClose : undefined}>
      <div
        className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-3xl border-2 border-amber-500/30 p-6 max-w-sm w-full shadow-2xl shadow-amber-500/20"
        onClick={(e) => e.stopPropagation()}
      >
        {/* 标题 */}
        <div className="text-center mb-5">
          <div className="inline-flex items-center gap-2 mb-1">
            <Sparkles className="text-amber-400" size={20} />
            <h2 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-amber-300 to-orange-400">
              水果机抽奖
            </h2>
            <Sparkles className="text-amber-400" size={20} />
          </div>
          <p className="text-slate-400 text-xs">三个转到同一水果即可获得该种子</p>
        </div>

        {/* 转盘 */}
        <div className="flex justify-center gap-2 mb-5">
          {reels.map((reel, i) => {
            const cfg = reel.finalType ? SEED_CONFIGS[reel.finalType] : null;
            return (
              <div
                key={i}
                className={`relative w-14 h-14 rounded-xl border-2 overflow-hidden flex items-center justify-center transition-all duration-300 ${
                  reel.spinning
                    ? "border-amber-400/50 bg-slate-700/50"
                    : allSame
                    ? "border-emerald-400/70 bg-emerald-400/10"
                    : "border-slate-600/50 bg-slate-800/50"
                }`}
              >
                {reel.spinning ? (
                  <div
                    className="absolute inset-0 flex flex-col"
                    style={{
                      animation: `spinReel 0.1s linear infinite`,
                    }}
                  >
                    {REEL_SYMBOLS.concat(REEL_SYMBOLS).map((t, idx) => (
                      <div
                        key={idx}
                        className="flex items-center justify-center shrink-0"
                        style={{ height: REEL_HEIGHT, fontSize: 28 }}
                      >
                        {SEED_CONFIGS[t].fruitEmoji}
                      </div>
                    ))}
                  </div>
                ) : cfg ? (
                  <span className="text-3xl" style={{ filter: allSame ? "drop-shadow(0 0 8px " + cfg.color + ")" : "none" }}>
                    {cfg.fruitEmoji}
                  </span>
                ) : (
                  <span className="text-slate-600 text-2xl">?</span>
                )}
              </div>
            );
          })}
        </div>

        {/* 结果展示 */}
        {showReward && (
          <div className="text-center mb-4 min-h-[3rem]">
            {allSame && result ? (
              rewardSeed ? (
                <div className="space-y-1">
                  <p className="text-emerald-300 text-sm font-medium">恭喜中奖！获得种子奖励</p>
                  <div className="flex items-center justify-center gap-1.5">
                    <span className="text-3xl">{SEED_CONFIGS[rewardSeed.type].fruitEmoji}</span>
                    <span className="text-amber-300 text-2xl font-bold">×{rewardSeed.amount}</span>
                    <span className="text-slate-400 text-sm">{SEED_CONFIGS[rewardSeed.type].name}种子</span>
                  </div>
                  <p className="text-slate-500 text-[10px]">已发放到农场，可直接种植</p>
                </div>
              ) : rewardSunlight > 0 ? (
                <div className="space-y-1">
                  <p className="text-amber-300 text-sm font-medium">恭喜中奖！该种子尚未解锁</p>
                  <div className="flex items-center justify-center gap-1.5">
                    <Sun size={18} className="text-yellow-400" />
                    <span className="text-yellow-300 text-2xl font-bold">+{rewardSunlight}</span>
                    <span className="text-slate-400 text-sm">阳光</span>
                  </div>
                  <p className="text-slate-500 text-[10px]">已折算为阳光价值发放</p>
                </div>
              ) : null
            ) : (
              <p className="text-slate-400 text-sm">很遗憾，三个未一致</p>
            )}
          </div>
        )}

        {/* 按钮 */}
        <button
          onClick={showReward ? onClose : spin}
          disabled={spinning}
          className={`w-full py-2.5 rounded-xl font-medium transition-all active:scale-95 ${
            spinning
              ? "bg-slate-700 text-slate-500 cursor-not-allowed"
              : showReward
              ? "bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-white"
              : "bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 text-white"
          }`}
        >
          {spinning ? "旋转中..." : showReward ? "再来一局" : "开始抽奖"}
        </button>
      </div>

      <style>{`
        @keyframes spinReel {
          0% { transform: translateY(0); }
          100% { transform: translateY(-${REEL_HEIGHT * REEL_SYMBOLS.length}px); }
        }
      `}</style>
    </div>
  );
}
