import { stealCropBatch } from "@/utils/rankingApi";
import { getUserInfo } from "@/utils/userInfo";
import { showToast } from "@/utils/toast";

const DEBOUNCE_MS = 5 * 1000;
const MAX_RETRY_MS = 8 * 1000;

interface PendingSteal {
  targetUuid: string;
  cropId: string;
  seedType: string;
  thiefUuid: string;
  thiefNickname: string;
}

let debounceTimer: number | null = null;
let retryTimer: number | null = null;
let retryCount = 0;
let initialized = false;
let syncing = false;
let pendingSteals: PendingSteal[] = [];

function clearRetry() {
  if (retryTimer !== null) {
    clearTimeout(retryTimer);
    retryTimer = null;
  }
}

function scheduleRetry() {
  clearRetry();
  retryCount += 1;
  const delay = Math.min(1000 * Math.pow(2, retryCount), MAX_RETRY_MS);
  retryTimer = window.setTimeout(() => {
    retryTimer = null;
    doSync();
  }, delay);
}

async function doSync() {
  if (syncing) return;
  if (pendingSteals.length === 0) return;

  syncing = true;
  const items = pendingSteals;
  pendingSteals = [];

  try {
    const result = await stealCropBatch(items);
    if (result.success) {
      retryCount = 0;
      clearRetry();
    } else if (result.code === "NO_STEALABLE_CROP") {
      // 永久性失败：作物已被偷/不存在，不重试、不重新入队
      showToast(result.message, "error");
      retryCount = 0;
      clearRetry();
    } else {
      // 临时错误：网络/同步失败，重试
      pendingSteals = [...items, ...pendingSteals];
      if (retryCount < 3) {
        scheduleRetry();
      } else {
        showToast(result.message, "error");
        retryCount = 0;
      }
    }
  } catch (e) {
    console.error("同步偷菜异常:", e);
    pendingSteals = [...items, ...pendingSteals];
    if (retryCount < 3) {
      scheduleRetry();
    } else {
      showToast("偷菜数据同步失败，请稍后再试", "error");
      retryCount = 0;
    }
  } finally {
    syncing = false;
    if (pendingSteals.length > 0 && retryCount === 0) {
      scheduleSync();
    }
  }
}

function scheduleSync() {
  if (debounceTimer !== null) {
    clearTimeout(debounceTimer);
  }
  debounceTimer = window.setTimeout(() => {
    debounceTimer = null;
    doSync();
  }, DEBOUNCE_MS);
}

export function queueSteal(targetUuid: string, cropId: string, seedType: string) {
  const userInfo = getUserInfo();
  if (!userInfo.uuid) return;

  if (pendingSteals.some((s) => s.cropId === cropId)) return;

  pendingSteals.push({
    targetUuid,
    cropId,
    seedType,
    thiefUuid: userInfo.uuid,
    thiefNickname: userInfo.nickname,
  });

  scheduleSync();
}

export function hasPendingSteals(): boolean {
  return pendingSteals.length > 0;
}

export function initStealSync() {
  if (initialized) return;
  initialized = true;

  const handleVisibility = () => {
    if (document.visibilityState === "hidden") {
      if (debounceTimer !== null) {
        clearTimeout(debounceTimer);
        debounceTimer = null;
      }
      doSync();
    }
  };

  document.addEventListener("visibilitychange", handleVisibility);

  return () => {
    document.removeEventListener("visibilitychange", handleVisibility);
    if (debounceTimer !== null) {
      clearTimeout(debounceTimer);
    }
    clearRetry();
    initialized = false;
  };
}
