import { create } from "zustand";
import { SeedType, SEED_CONFIGS } from "@/types/game";
import {
  DeliveryOrder,
  PlayerState,
  VehicleType,
  VEHICLE_TYPES,
} from "@/types/delivery";

const STORAGE_KEY_ORDERS = "delivery_available_orders";

interface DeliveryStore {
  availableOrders: DeliveryOrder[];
  currentOrder: DeliveryOrder | null;
  player: PlayerState;
  phase: "hub" | "loading" | "delivering";
  lastCompletedReward: { reward: number; multiplier: number } | null;

  setAvailableOrders: (orders: DeliveryOrder[]) => void;
  loadOrders: () => void;
  acceptOrder: (orderId: string) => boolean;
  cancelOrder: (discard?: boolean) => void;
  loadItem: (seedType: SeedType, quantity: number) => boolean;
  unloadItem: (seedType: SeedType, quantity: number) => void;
  setPhase: (phase: "hub" | "loading" | "delivering") => void;
  selectVehicle: (vehicle: VehicleType) => void;
  completeOrder: (reward: number, multiplier: number) => void;
  clearLastReward: () => void;
  reset: () => void;
  setFuel: (fuel: number) => void;
  addFuel: (amount: number) => void;
  consumeFuel: (amount: number) => void;
  setSpeedBoost: (durationMs: number) => void;
  setSlow: (durationMs: number) => void;
  startTestRun: () => void;
}

const initialPlayer: PlayerState = {
  vehicle: null,
  fuel: 100,
  speedBoostUntil: 0,
  slowUntil: 0,
};

export const useDeliveryStore = create<DeliveryStore>((set, get) => ({
  availableOrders: [],
  currentOrder: null,
  player: initialPlayer,
  phase: "hub",
  lastCompletedReward: null,

  setAvailableOrders: (orders) => {
    set({ availableOrders: orders });
    localStorage.setItem(STORAGE_KEY_ORDERS, JSON.stringify(orders));
  },

  loadOrders: () => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY_ORDERS);
      if (raw) {
        const orders = JSON.parse(raw) as DeliveryOrder[];
        set({ availableOrders: orders });
      }
    } catch (e) {
      console.error("加载订单失败", e);
    }
  },

  acceptOrder: (orderId) => {
    const order = get().availableOrders.find((o) => o.id === orderId);
    if (!order) return false;
    const vehicle = VEHICLE_TYPES.find((v) => v.id === order.vehicleId) || VEHICLE_TYPES[0];
    const newOrders = get().availableOrders.filter((o) => o.id !== orderId);
    set({
      currentOrder: { ...order, status: "accepted", loadedItems: {} },
      availableOrders: newOrders,
      phase: "loading",
      player: { ...initialPlayer, vehicle, fuel: vehicle.maxFuel },
    });
    localStorage.setItem(STORAGE_KEY_ORDERS, JSON.stringify(newOrders));
    return true;
  },

  cancelOrder: (discard) => {
    const order = get().currentOrder;
    if (!order) return;
    const isTestOrder = order.id.startsWith("test_");
    if (isTestOrder || discard) {
      set({
        currentOrder: null,
        phase: "hub",
        player: { ...initialPlayer },
      });
    } else {
      const newOrders = [...get().availableOrders, { ...order, status: "available" as const }];
      set({
        availableOrders: newOrders,
        currentOrder: null,
        phase: "hub",
        player: { ...initialPlayer },
      });
      localStorage.setItem(STORAGE_KEY_ORDERS, JSON.stringify(newOrders));
    }
  },

  loadItem: (seedType, quantity) => {
    const order = get().currentOrder;
    if (!order || order.status !== "accepted") return false;

    const loaded = order.loadedItems[seedType] || 0;
    set({
      currentOrder: {
        ...order,
        loadedItems: {
          ...order.loadedItems,
          [seedType]: loaded + quantity,
        },
      },
    });
    return true;
  },

  unloadItem: (seedType, quantity) => {
    const order = get().currentOrder;
    if (!order || order.status !== "accepted") return;

    const loaded = order.loadedItems[seedType] || 0;
    const canUnload = Math.min(quantity, loaded);
    if (canUnload <= 0) return;

    set({
      currentOrder: {
        ...order,
        loadedItems: {
          ...order.loadedItems,
          [seedType]: loaded - canUnload,
        },
      },
    });
  },

  setPhase: (phase) => set({ phase }),

  selectVehicle: (vehicle) =>
    set({ player: { ...get().player, vehicle, fuel: vehicle.maxFuel } }),

  completeOrder: (reward, multiplier) => {
    set({
      lastCompletedReward: { reward, multiplier },
      currentOrder: null,
      phase: "hub",
      player: { ...initialPlayer },
    });
  },

  clearLastReward: () => set({ lastCompletedReward: null }),

  setFuel: (fuel) => {
    const maxFuel = get().player.vehicle?.maxFuel || 100;
    set({ player: { ...get().player, fuel: Math.max(0, Math.min(maxFuel, fuel)) } });
  },

  addFuel: (amount) => {
    const maxFuel = get().player.vehicle?.maxFuel || 100;
    set({ player: { ...get().player, fuel: Math.min(maxFuel, get().player.fuel + amount) } });
  },

  consumeFuel: (amount) => {
    set({ player: { ...get().player, fuel: Math.max(0, get().player.fuel - amount) } });
  },

  setSpeedBoost: (durationMs) => {
    set({ player: { ...get().player, speedBoostUntil: Date.now() + durationMs } });
  },

  setSlow: (durationMs) => {
    set({ player: { ...get().player, slowUntil: Date.now() + durationMs } });
  },

  startTestRun: () => {
    const vehicle = VEHICLE_TYPES[0];
    const testOrder: DeliveryOrder = {
      id: "test_" + Date.now(),
      conditions: [],
      targetWeight: 10,
      maxWeight: 50,
      vehicleId: vehicle.id,
      obstacles: [],
      baseReward: 0,
      createdAt: Date.now(),
      status: "loaded",
      loadedItems: {},
    };
    set({
      currentOrder: testOrder,
      phase: "delivering",
      player: { ...initialPlayer, vehicle, fuel: vehicle.maxFuel },
    });
  },

  reset: () => {
    set({
      availableOrders: [],
      currentOrder: null,
      player: initialPlayer,
      phase: "hub",
    });
    localStorage.setItem(STORAGE_KEY_ORDERS, JSON.stringify([]));
  },
}));

// Store 创建后立即加载订单
useDeliveryStore.getState().loadOrders();

export function isOrderFullyLoaded(order: DeliveryOrder): boolean {
  const loaded: Partial<Record<SeedType, number>> = order.loadedItems;

  for (const cond of order.conditions) {
    if (cond.type === "exact") {
      const n = loaded[cond.seedType] || 0;
      if (n !== cond.count) return false;
    } else if (cond.type === "min") {
      const n = loaded[cond.seedType] || 0;
      if (n < cond.count) return false;
    } else if (cond.type === "max") {
      const n = loaded[cond.seedType] || 0;
      if (n > cond.count) return false;
    } else if (cond.type === "forbidden") {
      for (const s of cond.seedTypes) {
        if ((loaded[s] || 0) > 0) return false;
      }
    }
  }

  const totalWeight = Object.entries(loaded).reduce(
    (sum, [type, qty]) => sum + (qty || 0) * (SEED_CONFIGS[type as SeedType]?.weight || 0),
    0
  );
  if (totalWeight < order.targetWeight) return false;
  if (totalWeight > order.maxWeight) return false;

  return true;
}

export function getVehicleById(id: string): VehicleType {
  return VEHICLE_TYPES.find((v) => v.id === id) || VEHICLE_TYPES[0];
}

export function suggestVehicle(order: DeliveryOrder): VehicleType {
  const totalWeight = order.targetWeight;
  return (
    VEHICLE_TYPES.find((v) => v.capacity >= totalWeight) || VEHICLE_TYPES[VEHICLE_TYPES.length - 1]
  );
}
