import { create } from "zustand";
import {
  SeedType,
  GrowthStage,
  SEED_CONFIGS,
  PLOT_UNLOCK_COSTS,
  PlantedCrop,
  FarmState,
  StolenRecord,
} from "@/types/game";
import { useGameStore } from "./useGameStore";
import { fetchPlayerFarm } from "@/utils/rankingApi";
import { getUserInfo } from "@/utils/userInfo";

const STORAGE_KEY = "block_game_farm";
const STEAL_KEY = "block_game_steal";
const MAX_STEAL_PER_DAY = 5;

const getTodayStr = () => new Date().toISOString().slice(0, 10);

const loadStealData = (): { date: string; count: number; stolenKeys: string[] } => {
  try {
    const raw = localStorage.getItem(STEAL_KEY);
    if (raw) {
      const data = JSON.parse(raw);
      if (data.date === getTodayStr()) return { date: data.date, count: data.count || 0, stolenKeys: data.stolenKeys || [] };
    }
  } catch {
    /* 忽略读取失败 */
  }
  return { date: getTodayStr(), count: 0, stolenKeys: [] };
};

const saveStealData = (data: { date: string; count: number; stolenKeys: string[] }) => {
  try {
    localStorage.setItem(STEAL_KEY, JSON.stringify(data));
  } catch {
    /* 忽略保存失败 */
  }
};

let saveFarmTimer: number | null = null;
let saveFarmPending: unknown = null;
function flushSaveFarm() {
  saveFarmTimer = null;
  const p = saveFarmPending;
  saveFarmPending = null;
  if (!p) return;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(p));
  } catch (e) {
    console.error("保存农场数据失败", e);
  }
}

const createEmptySeedCount = (): Record<SeedType, number> => ({
  cabbage: 0, sunflower: 0, tomato: 0, corn: 0, strawberry: 0,
  carrot: 0, cucumber: 0, watermelon: 0, grapes: 0, eggplant: 0, kiwi: 0,
});

const createEmptySeedInventory = createEmptySeedCount;
const createEmptyWarehouse = createEmptySeedCount;

const DEFAULT_TOTAL_PLOTS = 9;

interface FarmStore extends FarmState {
  loadFarm: () => void;
  saveFarm: () => void;

  unlockSeed: (seedType: SeedType) => { success: boolean; message: string };
  unlockPlot: () => { success: boolean; message: string };

  buySeed: (seedType: SeedType) => { success: boolean; message: string };
  // 奖励发放：直接获得种子并解锁（不消耗阳光），用于抽奖/任务奖励等
  grantSeed: (seedType: SeedType) => void;
  plantSeed: (seedType: SeedType, plotIndex: number) => { success: boolean; message: string };
  harvestCrop: (cropId: string) => { success: boolean; message: string };
  clearStolenRecord: (plotIndex: number) => { success: boolean; message: string };
  sellFruit: (seedType: SeedType, amount: number) => { success: boolean; message: string };
  sellAllFruits: () => { success: boolean; totalCoins: number };

  waterCrop: (cropId: string) => { success: boolean; message: string };
  weedCrop: (cropId: string) => { success: boolean; message: string };
  fertilizeCrop: (cropId: string) => { success: boolean; message: string };

  getGrowthStage: (crop: PlantedCrop) => GrowthStage;
  getStageProgress: (crop: PlantedCrop) => number;
  getTimeRemaining: (crop: PlantedCrop) => { hours: number; minutes: number };
  isReadyToHarvest: (crop: PlantedCrop) => boolean;
  getCropAtPlot: (plotIndex: number) => PlantedCrop | undefined;
  getAvailablePlot: () => number | -1;

  debugAddSunlight: (amount: number) => void;
  debugAdvanceCrop: (cropId: string, hours: number) => void;
  debugRipenCrop: (cropId: string) => Promise<void>;

  _fieldDirty: boolean;
  _markFieldDirty: () => void;
  _consumeFieldDirty: () => boolean;

  stealCount: number;
  stealDate: string;
  stolenKeys: string[];
  getRemainingSteals: () => number;
  hasStolenCrop: (playerUuid: string, cropId: string) => boolean;
  stealFruit: (seedType: SeedType, playerUuid: string, cropId: string) => { success: boolean; message: string };

  syncStolenFromCloud: () => Promise<number>;
}

export const useFarmStore = create<FarmStore>((set, get) => {
  const initialSteal = loadStealData();
  return {
  seedInventory: createEmptySeedInventory(),
  plantedCrops: [],
  warehouse: createEmptyWarehouse(),
  totalPlots: DEFAULT_TOTAL_PLOTS,
  unlockedSeeds: ["cabbage", "carrot", "cucumber"],
  openedPlots: 1,
  stolenRecords: [],
  _fieldDirty: false,
  _markFieldDirty: () => set({ _fieldDirty: true }),
  _consumeFieldDirty: () => {
    const dirty = get()._fieldDirty;
    if (dirty) set({ _fieldDirty: false });
    return dirty;
  },

  stealCount: initialSteal.count,
  stealDate: initialSteal.date,
  stolenKeys: initialSteal.stolenKeys,
  getRemainingSteals: () => {
    const { stealCount, stealDate } = get();
    if (stealDate !== getTodayStr()) return MAX_STEAL_PER_DAY;
    return Math.max(0, MAX_STEAL_PER_DAY - stealCount);
  },
  hasStolenCrop: (playerUuid, cropId) => {
    const { stolenKeys, stealDate } = get();
    if (stealDate !== getTodayStr()) return false;
    return stolenKeys.includes(`${playerUuid}:${cropId}`);
  },
  stealFruit: (seedType, playerUuid, cropId) => {
    const state = get();
    const today = getTodayStr();
    let { stealCount, stealDate, stolenKeys } = state;
    if (stealDate !== today) {
      stealCount = 0;
      stolenKeys = [];
      stealDate = today;
    }
    const key = `${playerUuid}:${cropId}`;
    if (stolenKeys.includes(key)) {
      return { success: false, message: "这个作物今天已经偷过了" };
    }
    if (stealCount >= MAX_STEAL_PER_DAY) {
      return { success: false, message: `今天偷菜次数已用完（${MAX_STEAL_PER_DAY}/${MAX_STEAL_PER_DAY}）` };
    }
    const newWarehouse = { ...state.warehouse, [seedType]: (state.warehouse[seedType] || 0) + 1 };
    const newCount = stealCount + 1;
    const newStolenKeys = [...stolenKeys, key];
    const stealData = { date: today, count: newCount, stolenKeys: newStolenKeys };
    saveStealData(stealData);
    set({ warehouse: newWarehouse, stealCount: newCount, stealDate: today, stolenKeys: newStolenKeys });
    get().saveFarm();
    return { success: true, message: `偷到了 1 个${SEED_CONFIGS[seedType].name}！` };
  },

  syncStolenFromCloud: async () => {
    try {
      if (get()._fieldDirty) return 0;

      const userInfo = getUserInfo();
      if (!userInfo.uuid) return 0;

      const cloudFarm = await fetchPlayerFarm(userInfo.uuid);
      if (!cloudFarm) return 0;

      const state = get();
      const cloudSnapshotAt = cloudFarm.snapshotAt || 0;

      // ========== 1. 处理作物（plantedCrops） ==========
      // 本地作物中，plantedAt > cloudSnapshotAt 的是刚种还没同步的，必须保留
      // 其余作物如果在云端没有，则说明是被偷了
      const cloudCropIds = new Set((cloudFarm.plantedCrops || []).map((c) => c.id));
      const removedCropIds: string[] = [];

      for (const c of state.plantedCrops) {
        if (c.plantedAt > cloudSnapshotAt) continue; // 本地新种，保留
        if (!cloudCropIds.has(c.id)) {
          removedCropIds.push(c.id);
        }
      }

      const newCrops = state.plantedCrops.filter((c) => !removedCropIds.includes(c.id));

      // ========== 2. 处理被偷记录（stolenRecords） ==========
      // 先找出每个 plotIndex 上最新的作物种植时间（用于判断被偷记录是否已过时）
      const plotLatestPlantedAt: Record<number, number> = {};
      for (const c of newCrops) {
        const prev = plotLatestPlantedAt[c.plotIndex];
        if (prev === undefined || c.plantedAt > prev) {
          plotLatestPlantedAt[c.plotIndex] = c.plantedAt;
        }
      }

      const stolenKey = (r: StolenRecord | { plotIndex: number; seedType: string; stolenAt: number }) =>
        `${r.plotIndex}:${r.seedType}:${r.stolenAt}`;

      // 合并云端的新被偷记录
      const cloudStolen = cloudFarm.stolenRecords || [];
      const mergedStolenMap: Record<string, StolenRecord> = {};

      for (const r of state.stolenRecords || []) {
        mergedStolenMap[stolenKey(r)] = r;
      }
      for (const r of cloudStolen) {
        const key = stolenKey(r as StolenRecord);
        if (!mergedStolenMap[key]) {
          mergedStolenMap[key] = r as StolenRecord;
        }
      }

      // 过滤：如果某个 plotIndex 上已经有了比被偷记录新的作物，说明这条被偷记录已经被清理过了
      const finalStolenRecords: StolenRecord[] = [];
      for (const r of Object.values(mergedStolenMap)) {
        const latestAt = plotLatestPlantedAt[r.plotIndex];
        if (latestAt !== undefined && latestAt > r.stolenAt) {
          continue; // 本地已经在这块地上种了更新的作物，丢弃旧被偷记录
        }
        finalStolenRecords.push(r);
      }

      // ========== 3. 判断是否有变化 ==========
      const cropsChanged = removedCropIds.length > 0 || newCrops.length !== state.plantedCrops.length;
      const stolenChanged = finalStolenRecords.length !== (state.stolenRecords || []).length;
      if (!cropsChanged && !stolenChanged) {
        // 长度一样也可能内容不同，简单比较 key
        const curKeys = new Set((state.stolenRecords || []).map(stolenKey));
        const newKeys = new Set(finalStolenRecords.map(stolenKey));
        let keysDiff = curKeys.size !== newKeys.size;
        if (!keysDiff) {
          for (const k of curKeys) {
            if (!newKeys.has(k)) { keysDiff = true; break; }
          }
        }
        if (!keysDiff && removedCropIds.length === 0) return 0;
      }

      set({
        plantedCrops: newCrops,
        stolenRecords: finalStolenRecords,
      });
      get().saveFarm();

      return removedCropIds.length + Math.abs(finalStolenRecords.length - (state.stolenRecords || []).length);
    } catch (e) {
      console.error("同步云端被偷记录失败:", e);
      return 0;
    }
  },

  loadFarm: () => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const data = JSON.parse(raw);
        // 升级：确保 totalPlots 不低于当前版本的默认值
        const newTotalPlots = Math.max(data.totalPlots || 0, DEFAULT_TOTAL_PLOTS);
        // 升级：确保免费解锁的种子都已解锁
        const freeSeeds = (Object.keys(SEED_CONFIGS) as SeedType[]).filter(
          (s) => SEED_CONFIGS[s].unlockCost === 0
        );
        const savedSeeds = data.unlockedSeeds || [];
        const mergedUnlocked = Array.from(new Set([...savedSeeds, ...freeSeeds]));
        set({
          seedInventory: { ...createEmptySeedInventory(), ...data.seedInventory },
          plantedCrops: data.plantedCrops || [],
          warehouse: { ...createEmptyWarehouse(), ...data.warehouse },
          totalPlots: newTotalPlots,
          unlockedSeeds: mergedUnlocked,
          openedPlots: data.openedPlots || 1,
          stolenRecords: data.stolenRecords || [],
        });
      }
    } catch (e) {
      console.error("加载农场数据失败", e);
    }
  },

  saveFarm: () => {
    try {
      const { seedInventory, plantedCrops, warehouse, totalPlots, unlockedSeeds, openedPlots, stolenRecords } = get();
      saveFarmPending = { seedInventory, plantedCrops, warehouse, totalPlots, unlockedSeeds, openedPlots, stolenRecords };
      if (saveFarmTimer !== null) {
        clearTimeout(saveFarmTimer);
      }
      saveFarmTimer = window.setTimeout(flushSaveFarm, 500);
    } catch (e) {
      console.error("保存农场数据失败", e);
    }
  },

  unlockSeed: (seedType) => {
    const { unlockedSeeds } = get();
    if (unlockedSeeds.includes(seedType)) {
      return { success: false, message: "该作物已解锁" };
    }
    const config = SEED_CONFIGS[seedType];
    const sunlight = useGameStore.getState().sunlight;
    if (sunlight < config.unlockCost) {
      return { success: false, message: `阳光不足，需要 ${config.unlockCost} ☀️` };
    }

    useGameStore.getState().spendSunlight(config.unlockCost);
    set({ unlockedSeeds: [...unlockedSeeds, seedType] });
    get().saveFarm();
    return { success: true, message: `解锁了${config.name}种子！` };
  },

  unlockPlot: () => {
    const { openedPlots, totalPlots } = get();
    if (openedPlots >= totalPlots) {
      return { success: false, message: "所有地块已开垦" };
    }
    const cost = PLOT_UNLOCK_COSTS[openedPlots];
    const sunlight = useGameStore.getState().sunlight;
    if (sunlight < cost) {
      return { success: false, message: `阳光不足，需要 ${cost} ☀️` };
    }

    useGameStore.getState().spendSunlight(cost);
    set({ openedPlots: openedPlots + 1 });
    get().saveFarm();
    get()._markFieldDirty();
    return { success: true, message: `开垦了一块新地！` };
  },

  buySeed: (seedType) => {
    const { unlockedSeeds } = get();
    if (!unlockedSeeds.includes(seedType)) {
      return { success: false, message: "请先解锁该作物" };
    }
    const config = SEED_CONFIGS[seedType];
    const sunlight = useGameStore.getState().sunlight;
    if (sunlight < config.sunlightPrice) {
      return { success: false, message: `阳光不足，需要 ${config.sunlightPrice} ☀️` };
    }

    useGameStore.getState().spendSunlight(config.sunlightPrice);
    const newInventory = { ...get().seedInventory };
    newInventory[seedType] = (newInventory[seedType] || 0) + 1;
    set({ seedInventory: newInventory });
    get().saveFarm();
    return { success: true, message: `购买了 1 颗${config.name}种子` };
  },

  grantSeed: (seedType) => {
    const { unlockedSeeds, seedInventory } = get();
    const newUnlocked = unlockedSeeds.includes(seedType)
      ? unlockedSeeds
      : [...unlockedSeeds, seedType];
    const newInventory = { ...seedInventory };
    newInventory[seedType] = (newInventory[seedType] || 0) + 1;
    set({ unlockedSeeds: newUnlocked, seedInventory: newInventory });
    get().saveFarm();
    get()._markFieldDirty();
  },

  plantSeed: (seedType, plotIndex) => {
    const { seedInventory, plantedCrops, totalPlots, openedPlots, getCropAtPlot, stolenRecords } = get();

    if (plotIndex < 0 || plotIndex >= totalPlots) {
      return { success: false, message: "无效的地块" };
    }
    if (plotIndex >= openedPlots) {
      return { success: false, message: "该地块未开垦" };
    }
    if (getCropAtPlot(plotIndex)) {
      return { success: false, message: "该地块已有作物" };
    }
    if (!seedInventory[seedType] || seedInventory[seedType] <= 0) {
      return { success: false, message: "没有该类型的种子" };
    }

    const newInventory = { ...seedInventory };
    newInventory[seedType] -= 1;

    const newCrop: PlantedCrop = {
      id: `crop_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      seedType,
      plantedAt: Date.now(),
      plotIndex,
    };

    // 清理该地块的被偷记录
    const newStolenRecords = stolenRecords.filter((r) => r.plotIndex !== plotIndex);

    set({
      seedInventory: newInventory,
      plantedCrops: [...plantedCrops, newCrop],
      stolenRecords: newStolenRecords,
    });
    get().saveFarm();
    get()._markFieldDirty();
    return { success: true, message: `种下了${SEED_CONFIGS[seedType].name}种子` };
  },

  harvestCrop: (cropId) => {
    const { plantedCrops, warehouse, isReadyToHarvest } = get();
    const crop = plantedCrops.find((c) => c.id === cropId);
    if (!crop) {
      return { success: false, message: "作物不存在" };
    }
    if (!isReadyToHarvest(crop)) {
      return { success: false, message: "作物还未成熟" };
    }

    const newWarehouse = { ...warehouse };
    newWarehouse[crop.seedType] = (newWarehouse[crop.seedType] || 0) + 1;

    set({
      plantedCrops: plantedCrops.filter((c) => c.id !== cropId),
      warehouse: newWarehouse,
    });
    get().saveFarm();
    get()._markFieldDirty();
    return { success: true, message: `收获了 1 个${SEED_CONFIGS[crop.seedType].name}` };
  },

  clearStolenRecord: (plotIndex) => {
    const { stolenRecords } = get();
    const record = stolenRecords.find((r) => r.plotIndex === plotIndex);
    if (!record) {
      return { success: false, message: "该地块没有被偷记录" };
    }
    set({
      stolenRecords: stolenRecords.filter((r) => r.plotIndex !== plotIndex),
    });
    get().saveFarm();
    get()._markFieldDirty();
    return { success: true, message: `${SEED_CONFIGS[record.seedType].name}被偷了，什么也没得到` };
  },

  sellFruit: (seedType, amount) => {
    const { warehouse } = get();
    const available = warehouse[seedType] || 0;
    if (available < amount || amount <= 0) {
      return { success: false, message: "仓库中数量不足" };
    }

    const config = SEED_CONFIGS[seedType];
    const totalCoins = config.fruitCoins * amount;

    const newWarehouse = { ...warehouse };
    newWarehouse[seedType] -= amount;

    useGameStore.getState().addCoins(totalCoins);
    set({ warehouse: newWarehouse });
    get().saveFarm();
    return { success: true, message: `卖出 ${amount} 个${config.name}，获得 ${totalCoins} 积分` };
  },

  sellAllFruits: () => {
    const { warehouse } = get();
    let totalCoins = 0;
    const newWarehouse = createEmptyWarehouse();

    for (const seedType of Object.keys(warehouse) as SeedType[]) {
      const count = warehouse[seedType] || 0;
      if (count > 0) {
        totalCoins += SEED_CONFIGS[seedType].fruitCoins * count;
      }
    }

    if (totalCoins > 0) {
      useGameStore.getState().addCoins(totalCoins);
    }
    set({ warehouse: newWarehouse });
    get().saveFarm();
    return { success: true, totalCoins };
  },

  waterCrop: (cropId) => {
    const { plantedCrops, isReadyToHarvest } = get();
    const crop = plantedCrops.find((c) => c.id === cropId);
    if (!crop) {
      return { success: false, message: "作物不存在" };
    }
    if (isReadyToHarvest(crop)) {
      return { success: false, message: "作物已成熟，无需浇水" };
    }
    const cost = 2;
    const sunlight = useGameStore.getState().sunlight;
    if (sunlight < cost) {
      return { success: false, message: `阳光不足，需要 ${cost} ☀️` };
    }

    useGameStore.getState().spendSunlight(cost);
    const hours = 1;
    const updated = plantedCrops.map((c) =>
      c.id === cropId
        ? { ...c, plantedAt: c.plantedAt - hours * 60 * 60 * 1000 }
        : c
    );
    set({ plantedCrops: updated });
    get().saveFarm();
    get()._markFieldDirty();
    return { success: true, message: `浇水成功！生长时间 -${hours} 小时` };
  },

  weedCrop: (cropId) => {
    const { plantedCrops, isReadyToHarvest } = get();
    const crop = plantedCrops.find((c) => c.id === cropId);
    if (!crop) {
      return { success: false, message: "作物不存在" };
    }
    if (isReadyToHarvest(crop)) {
      return { success: false, message: "作物已成熟，无需除草" };
    }
    const cost = 5;
    const sunlight = useGameStore.getState().sunlight;
    if (sunlight < cost) {
      return { success: false, message: `阳光不足，需要 ${cost} ☀️` };
    }

    useGameStore.getState().spendSunlight(cost);
    const hours = 3;
    const updated = plantedCrops.map((c) =>
      c.id === cropId
        ? { ...c, plantedAt: c.plantedAt - hours * 60 * 60 * 1000 }
        : c
    );
    set({ plantedCrops: updated });
    get().saveFarm();
    get()._markFieldDirty();
    return { success: true, message: `除草成功！生长时间 -${hours} 小时` };
  },

  fertilizeCrop: (cropId) => {
    const { plantedCrops, isReadyToHarvest } = get();
    const crop = plantedCrops.find((c) => c.id === cropId);
    if (!crop) {
      return { success: false, message: "作物不存在" };
    }
    if (isReadyToHarvest(crop)) {
      return { success: false, message: "作物已成熟，无需施肥" };
    }
    const cost = 10;
    const sunlight = useGameStore.getState().sunlight;
    if (sunlight < cost) {
      return { success: false, message: `阳光不足，需要 ${cost} ☀️` };
    }

    useGameStore.getState().spendSunlight(cost);
    const hours = 8;
    const updated = plantedCrops.map((c) =>
      c.id === cropId
        ? { ...c, plantedAt: c.plantedAt - hours * 60 * 60 * 1000 }
        : c
    );
    set({ plantedCrops: updated });
    get().saveFarm();
    get()._markFieldDirty();
    return { success: true, message: `施肥成功！生长时间 -${hours} 小时` };
  },

  getGrowthStage: (crop) => {
    const config = SEED_CONFIGS[crop.seedType];
    const elapsedMs = Date.now() - crop.plantedAt;
    const totalMs = config.growthHours * 60 * 60 * 1000;
    const progress = Math.min(1, elapsedMs / totalMs);

    // 按比例划分：幼苗 0–33%，开花 33–67%，结果 67–100%
    if (progress < 1 / 3) return "seedling";
    if (progress < 2 / 3) return "flowering";
    return "fruiting";
  },

  getStageProgress: (crop) => {
    const config = SEED_CONFIGS[crop.seedType];
    const elapsedMs = Date.now() - crop.plantedAt;
    const totalMs = config.growthHours * 60 * 60 * 1000;
    return Math.min(1, elapsedMs / totalMs);
  },

  getTimeRemaining: (crop) => {
    const config = SEED_CONFIGS[crop.seedType];
    const elapsedMs = Date.now() - crop.plantedAt;
    const totalMs = config.growthHours * 60 * 60 * 1000;
    const remainingMs = Math.max(0, totalMs - elapsedMs);
    const totalMinutes = Math.ceil(remainingMs / (1000 * 60));
    return {
      hours: Math.floor(totalMinutes / 60),
      minutes: totalMinutes % 60,
    };
  },

  isReadyToHarvest: (crop) => {
    return get().getStageProgress(crop) >= 1;
  },

  getCropAtPlot: (plotIndex) => {
    return get().plantedCrops.find((c) => c.plotIndex === plotIndex);
  },

  getAvailablePlot: () => {
    const { openedPlots, getCropAtPlot } = get();
    for (let i = 0; i < openedPlots; i++) {
      if (!getCropAtPlot(i)) return i;
    }
    return -1;
  },

  debugAddSunlight: (amount) => {
    useGameStore.getState().addSunlight(amount);
  },

  debugAdvanceCrop: (cropId, hours) => {
    const { plantedCrops } = get();
    const updated = plantedCrops.map((c) =>
      c.id === cropId
        ? { ...c, plantedAt: c.plantedAt - hours * 60 * 60 * 1000 }
        : c
    );
    set({ plantedCrops: updated });
    get().saveFarm();
  },

  debugRipenCrop: async (cropId) => {
    const { plantedCrops } = get();
    const crop = plantedCrops.find((c) => c.id === cropId);
    if (!crop) return;
    const config = SEED_CONFIGS[crop.seedType];
    // 让作物成熟 + 超过1小时（可被偷）
    const targetElapsed = config.growthHours * 3600000 + 3700000; // 多100秒避免边界
    const newPlantedAt = Date.now() - targetElapsed;
    const updated = plantedCrops.map((c) =>
      c.id === cropId ? { ...c, plantedAt: newPlantedAt } : c
    );
    set({ plantedCrops: updated });
    get().saveFarm();
    get()._markFieldDirty();
  },
}});

useFarmStore.getState().loadFarm();
